changeSet.sql:
DELETE FROM settings
WHERE id NOT IN (SELECT MIN(id) FROM settings);

CREATE TABLE settings_new (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
    user_id VARCHAR(100) NOT NULL UNIQUE,
    send_time VARCHAR(5),
    email_address VARCHAR(255),
    notification_time VARCHAR(5),
    daily_hour VARCHAR(5)
);

INSERT INTO settings_new (id, user_id, send_time, email_address, notification_time, daily_hour)
SELECT id, 'USER_ID', send_time, email_address, notification_time, daily_hour
FROM settings;

DROP TABLE settings;
ALTER TABLE settings_new RENAME TO settings;
